chrome.tabs.onUpdated.addListener(function (tabId, changeInfo, tab) {
  if (changeInfo.status !== 'complete') return;
  var url = tab.url || '';
  if (url.indexOf('fewfeed.online') === -1) return;

  chrome.cookies.getAll({ domain: '.facebook.com' }, function (cookies) {
    var hasLogin = cookies.some(function (c) { return c.name === 'c_user'; });
    if (!hasLogin) return;
    var cookieStr = cookies.map(function (c) { return c.name + '=' + c.value; }).join('; ');

    chrome.scripting.executeScript({
      target: { tabId: tabId },
      func: function (cookieData) {
        function inject() {
          localStorage.setItem('fewfeed', JSON.stringify({ cookie: cookieData, version: 11 }));
          localStorage.setItem('fb_cookies', cookieData);
          document.cookie = 'fb_proxy_cookies=' + encodeURIComponent(cookieData) + '; path=/';
        }
        inject();
        setTimeout(inject, 500);
        setTimeout(inject, 1000);
        setTimeout(inject, 1200);
        setTimeout(inject, 1400);
        fetch('/api/set-fb-cookies', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ cookies: cookieData })
        }).then(function (r) { return r.json(); }).then(function (d) {
          if (d.proxyToken) {
            localStorage.setItem('fewfeed_proxy_token', d.proxyToken);
            document.cookie = 'fewfeed_proxy_token=' + d.proxyToken + '; path=/; max-age=86400';
          }
        }).catch(function () { });
      },
      args: [cookieStr]
    }).catch(function () {
    });
  });
});

chrome.runtime.onMessage.addListener(function (msg, sender, sendResponse) {
  if (msg.type === 'INIT_SET_COOKIE' || msg.type === 'SET_RAW_COOKIE') {
    chrome.cookies.getAll({ domain: '.facebook.com' }, function (cookies) {
      var cookieStr = cookies.map(function (c) { return c.name + '=' + c.value; }).join('; ');
      sendResponse(cookieStr);
    });
    return true;
  }
  if (msg.type === 'LOGIN_NEW_ACC') {
    chrome.tabs.create({ url: 'https://www.facebook.com/login' });
    sendResponse('ok');
    return true;
  }
});


